            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xE8D304113CDA237BULL) + aOUSaltF[((aIndex + 237U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xD26925185043B831ULL;
