            //
            aIngress = (RotL64(aVaporLaneA[((aIndex + 5097U)) & S_BLOCK1], 51U) ^ RotL64(aVaporLaneB[((aIndex + 4058U)) & S_BLOCK1], 34U));
            aIngress ^= (RotL64(aWindLaneB[((aIndex + 2276U)) & S_BLOCK1], 43U) ^ RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 3373U)) & S_BLOCK1], 21U));
