            aOrbiterK = ((aWandererH + RotL64(aScatter, 18U)) + 0x5CC6526E43267ED2ULL) + aOASaltB[(((511U - aIndex) + 155U)) & S_SALT1];
            aOrbiterH = (aWandererI + RotL64(aCross, 37U)) + 0x7C179DF6C8BCC106ULL;
            aOrbiterB = (((aWandererE + RotL64(aPrevious, 57U)) + RotL64(aCarry, 27U)) + 0x4B6293BBC2113BA8ULL) + aOASaltE[(((511U - aIndex) + 31U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aIngress, 43U)) + 0x45DD24DEFDD0C51CULL) + aOASaltG[((aIndex + 58U)) & S_SALT1];
            aOrbiterI = (((aWandererA + RotL64(aScatter, 27U)) + RotL64(aCarry, 19U)) + 0x92BDC23691BFAA70ULL) + aOASaltH[((aIndex + 203U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aCross, 12U)) + 0xCFD08ED222D9FD85ULL) + aOASaltD[(((511U - aIndex) + 190U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 51U)) + 0x13D6746BCE12AD1AULL;
